'use strict';
import {chapters, parts, sources, type Chapter, type Exercise} from './course';

// The page renders generated lesson fragments. Course data itself uses the
// strongly typed Chapter and Exercise contracts in course.ts.
declare const WASM_BASE64:string;
declare const SQLJS_LICENSE:string;
const $=(s:string,r:ParentNode=document):any=>r.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='backend-fieldnotes-v1';
let progress:any={version:1,answers:{},notes:{},read:[],last:1,theme:'light'},storageOK=true,active=0,labState:any={},searchTimer:any;
const orderLength=(exercise:Exercise):number=>exercise.type==='order'?exercise.steps.length:-1;
function validProgress(p){
 if(!p||p.version!==1||!p.answers||typeof p.answers!=='object'||Array.isArray(p.answers))throw Error('รูปแบบไฟล์ไม่ตรงหลักสูตรรุ่น 1');
 const clean={version:1,answers:{},notes:{},read:[],last:1,theme:p.theme==='dark'?'dark':'light'};
 for(const c of chapters){
  for(let i=0;i<c.exercises.length;i++){
   const id=c.id+'-'+i,a=p.answers[id];
   if(!a||typeof a!=='object')continue;
   clean.answers[id]={value:typeof a.value==='string'?a.value.slice(0,12000):Number.isInteger(a.value)?a.value:Array.isArray(a.value)&&a.value.length===orderLength(c.exercises[i])&&new Set(a.value).size===a.value.length&&a.value.every(v=>Number.isInteger(v)&&v>=0&&v<a.value.length)?a.value:undefined,correct:a.correct===true,attempts:Math.max(0,Math.min(Number(a.attempts)||0,10000)),hint:a.hint===true,feedback:typeof a.feedback==='string'?a.feedback.slice(0,2000):''};
  }
  if(typeof p.notes?.[c.id]==='string')clean.notes[c.id]=p.notes[c.id].slice(0,20000);
  if(Array.isArray(p.read)&&p.read.includes(c.id))clean.read.push(c.id);
 }
 if(Number.isInteger(p.last)&&p.last>=1&&p.last<=21)clean.last=p.last;
 return clean;
}
try{const raw=localStorage.getItem(key);if(raw)progress=validProgress(JSON.parse(raw));}catch(e){storageOK=false;}
function save(){try{localStorage.setItem(key,JSON.stringify(progress));storageOK=true;}catch(e){storageOK=false;}if(!storageOK){$('#storage-message').hidden=false;$('#storage-message').textContent='เบราว์เซอร์นี้บันทึกความคืบหน้าไม่ได้ ใช้ “ส่งออกความคืบหน้า” เก็บไฟล์ก่อนปิดหน้า';}}
document.documentElement.dataset.theme=progress.theme;
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3500);}
function countDone(){return (Object.values(progress.answers) as any[]).filter(a=>a.correct).length;}
function passed(c){return c.exercises.every((_,i)=>progress.answers[c.id+'-'+i]?.correct);}
function updateNav(){
 $('#chapter-nav').innerHTML=`<a class="navlink ${active===0?'active':''}" href="#home" ${active===0?'aria-current="page"':''}><span>⌂</span><span>ภาพรวมหลักสูตร</span></a>`+parts.map((p,i)=>`<div class="group">ภาค ${i+1} · ${esc(p)}</div>`+chapters.filter(c=>c.part===i+1).map(c=>`<a class="navlink ${active===c.id?'active':''}" href="#chapter/${c.id}" ${active===c.id?'aria-current="page"':''}><span>${String(c.id).padStart(2,'0')}</span><span>${esc(c.title)}</span>${passed(c)?'<span class="tick" aria-label="แบบฝึกครบ">✓</span>':''}</a>`).join('')).join('');
 $('#progress-label').textContent=`แบบฝึก ${countDone()} / 63 ข้อ`;
 $('#progress-fill').style.width=(countDone()/63*100)+'%';
 $('#chapter-progress').textContent=`ผ่านครบ ${chapters.filter(passed).length} / 21 บท`;
 const label=$('#exercise-status');if(label&&active){const c=chapters[active-1];label.textContent=`ทำถูก ${c.exercises.filter((_,i)=>progress.answers[c.id+'-'+i]?.correct).length} / 3 ข้อ · ${passed(c)?'ผ่านแบบฝึกบทนี้แล้ว':'ลองทำใหม่ได้จนเข้าใจ'}`;}
}
function footer(){return `<footer class="footer"><p>Backend Fieldnotes · เนื้อหาภาษาไทยสำหรับผู้ใช้ C#/Unity ที่เริ่ม Backend จากศูนย์<br>ตัวทดลองทำงานในเครื่องคุณ ไม่มีการสมัครบัญชีหรือเรียก Supabase จริง · เอกสารอ้างอิงตรวจเมื่อ 10 ตุลาคม 2026</p><button class="small" data-action="export">ส่งออกความคืบหน้า</button> <button class="small" data-action="import">นำเข้าความคืบหน้า</button> <a href="#sources">แหล่งอ้างอิงและที่มา</a></footer>`;}
function home(){
 return `<section class="hero"><div><p class="eyebrow">A practical backend learning journal</p><h1>จากโค้ดในเครื่อง<br>สู่ระบบที่เชื่อถือได้</h1><p class="intro">เรียน Backend ผ่านเกม Cozy Shelter<br>ตั้งแต่ HTTP และ SQL จนถึง Auth และระบบเกมบน Server</p><p class="quiet">รู้ C# และ Unity แล้ว เริ่ม Backend จากศูนย์ได้ที่นี่ เรียนทีละบท ทดลองแนวคิดที่ซับซ้อน และทำแบบฝึกในเว็บพร้อมคำอธิบาย</p><a class="button primary" href="#chapter/${progress.last}">${countDone()||progress.read.length?'เรียนต่อ':'เริ่มบทแรก'} · บท ${progress.last}</a> <a class="button" href="#guide">วิธีใช้ห้องเรียน</a><div class="stats"><div><strong>21</strong><small>บทเรียนแยกชัดเจน</small></div><div><strong>63</strong><small>แบบฝึกตรวจคำตอบ</small></div><div><strong>18</strong><small>รูปแบบห้องทดลอง</small></div></div></div><div class="hero-art"><span class="eyebrow">Your first backend</span><div class="node" style="border:1px solid var(--line);padding:13px;border-radius:6px;margin-top:18px">Unity · ความตั้งใจของผู้เล่น</div><span class="arrow">↓ HTTP + Session</span><div class="node" style="border:1px solid var(--line);padding:13px;border-radius:6px">RPC · ตรวจเงื่อนไขและสิทธิ์</div><span class="arrow">↓ Transaction</span><div class="node" style="border:1px solid var(--line);padding:13px;border-radius:6px">PostgreSQL · ความจริงของเกม</div><p class="quiet" style="font-size:13px;margin:20px 0 0">คำถามที่เราจะตอบ: ใครเป็นผู้เล่น? มีสิทธิ์อะไร? เมื่อคำขอชนหรือหาย จะรักษาข้อมูลอย่างไร?</p></div></section><div class="section-head"><h2>เส้นทางการเรียน</h2><span class="quiet" style="font-size:13px">เลือกบทได้อิสระ · แนะนำเรียนตามลำดับ</span></div>`+parts.map((p,i)=>`<section class="home-group"><h2>ภาค ${i+1} / ${esc(p)}</h2><div class="chapter-list">${chapters.filter(c=>c.part===i+1).map(c=>`<a class="chapter-row" href="#chapter/${c.id}"><span class="index">${String(c.id).padStart(2,'0')}</span><div><h3>${esc(c.title)}</h3><p>${esc(c.goals[0])}</p><div class="meta">${c.duration} นาทีโดยประมาณ · 3 แบบฝึก ${passed(c)?'· ✓ ผ่านแล้ว':progress.read.includes(c.id)?'· อ่านแล้ว':''}</div></div></a>`).join('')}</div></section>`).join('')+footer();
}
function codeBlock(e,id){return `<div class="code-caption"><span>${esc(e.label)}</span><button class="small" data-copy="${id}">คัดลอกโค้ด</button></div><pre><code id="${id}">${esc(e.code)}</code></pre><ol class="annotations">${e.lines.map(t=>`<li>${esc(t)}</li>`).join('')}</ol>`;}
function defaultOrder(e){return e.steps.map((_,i)=>i).slice(1).concat(0);}
function exerciseHTML(c,e,i){
 const id=c.id+'-'+i,a=progress.answers[id]||{},prompt=`ข้อ ${i+1}. ${e.prompt}`;
 let input='';
 if(e.type==='mc') input=e.choices.map((s,j)=>`<label class="option"><input type="radio" name="answer-${id}" value="${j}" data-answer="${id}" ${a.value===j?'checked':''}><span>${esc(s)}</span></label>`).join('');
 if(e.type==='text') input=`<label for="answer-${id}" class="quiet" style="font-size:13px;display:block">คำตอบ (ใส่ตัวเลขได้ ไม่ต้องใส่หน่วย)</label><input id="answer-${id}" class="numeric-answer" inputmode="decimal" data-answer="${id}" value="${esc(a.value??'')}" autocomplete="off">`;
 if(e.type==='order'){
  const vals=Array.isArray(a.value)?a.value:defaultOrder(e);input=`<p class="quiet" style="font-size:13px">ใช้ปุ่มเลื่อนขึ้น/ลงเพื่อเรียงจากขั้นแรกถึงขั้นสุดท้าย</p><ol class="order-list">${vals.map((v,j)=>`<li><span>${j+1}. ${esc(e.steps[v])}</span><span class="tools"><button class="small" data-move="${id}" data-pos="${j}" data-direction="-1" aria-label="เลื่อนขั้น ${j+1} ขึ้น" ${j===0?'disabled':''}>↑</button><button class="small" data-move="${id}" data-pos="${j}" data-direction="1" aria-label="เลื่อนขั้น ${j+1} ลง" ${j===vals.length-1?'disabled':''}>↓</button></span></li>`).join('')}</ol>`;
 }
 if(e.type==='sql')input=`<p class="quiet" style="font-size:13px">SQL จริงใน SQLite sandbox · ตรวจผลกับข้อมูลมากกว่าหนึ่งชุด · ไม่ใช่ PostgreSQL Server</p><label for="answer-${id}">SQL ของคุณ</label><textarea id="answer-${id}" class="sql-editor" spellcheck="false" data-answer="${id}">${esc(a.value??e.starter)}</textarea><details><summary>ดูตารางและข้อมูลเริ่มต้น</summary>${schemaHelp()}</details>`;
 return `<section class="exercise" id="exercise-${id}"><div class="question-tag">${['พื้นฐาน','ประยุกต์','ท้าทาย'][i]} · ${e.type==='sql'?'SQL lab':e.type==='order'?'เรียงขั้นตอน':e.type==='text'?'คำนวณผล':'วิเคราะห์สถานการณ์'}</div><fieldset><legend>${esc(prompt)}</legend>${input}</fieldset><div class="exercise-actions"><button class="primary small" data-grade="${id}">ตรวจคำตอบ</button><button class="small" data-hint="${id}">คำใบ้</button><button class="small" data-reset="${id}">เริ่มข้อนี้ใหม่</button></div><div class="hint" id="hint-${id}" ${a.hint?'':'hidden'}>${esc(e.hint)}</div><div id="feedback-${id}" aria-live="polite">${a.feedback?`<div class="feedback ${a.correct?'success':'error'}">${esc(a.feedback)}</div>`:''}</div><details><summary>เปิดเฉลยและเหตุผล</summary><p style="margin-top:14px">${esc(e.why)}</p>${e.type==='sql'?`<pre><code>${esc(e.solution)}</code></pre>`:e.type==='mc'?`<p><strong>คำตอบ:</strong> ${esc(e.choices[e.answer])}</p>`:e.type==='text'?`<p><strong>คำตอบ:</strong> ${esc(e.answers[0])}</p>`:`<ol>${e.steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol>`}<p class="quiet">เปิดเฉลยไม่เพิ่มคะแนน ต้องตอบและตรวจด้วยตนเอง เกณฑ์นี้ใช้ช่วยเรียน ไม่ใช่ข้อสอบรับรองความสามารถ</p></details></section>`;
}
function schemaHelp(){return `<div class="table-wrap"><table><caption>ข้อมูลเริ่มต้นสำหรับ SQL ในเว็บ</caption><thead><tr><th>ตาราง</th><th>คอลัมน์</th><th>ข้อมูล</th></tr></thead><tbody><tr><td>players</td><td>id,name</td><td>A=Mali, B=Niran</td></tr><tr><td>items</td><td>id,name</td><td>wood=Wood, stone=Stone, seed=Seed, chair=Chair</td></tr><tr><td>inventory</td><td>user_id,item_id,quantity</td><td>A: wood 10, stone 4 / B: wood 3, seed 5</td></tr></tbody></table></div><p class="quiet">Primary Key: (user_id,item_id) · quantity มี NOT NULL และ CHECK ≥ 0 · Foreign Keys เปิดใช้งาน · แบบฝึกแต่ละครั้งเริ่มจากฐานข้อมูลใหม่</p>`;}
function lesson(c){return `<div class="lesson-top"><div class="breadcrumb"><a href="#home">หลักสูตร</a> / ภาค ${c.part} / บท ${c.id}</div><div class="lesson-title"><p class="eyebrow">Chapter ${String(c.id).padStart(2,'0')} / 21</p><h1>${esc(c.title)}</h1><div class="lesson-meta"><span>${c.duration} นาทีโดยประมาณ</span><span>3 แบบฝึกท้ายบท</span><span class="badge ${passed(c)?'good':''}">${passed(c)?'ผ่านแบบฝึกแล้ว':progress.read.includes(c.id)?'อ่านแล้ว':'เริ่มเรียนได้'}</span></div><p class="lead">${esc(c.lead)}</p><a class="button small" href="#chapter/${c.id}/exercises">ไปแบบฝึกท้ายบท ↓</a> <button class="small" data-read="${c.id}">${progress.read.includes(c.id)?'✓ อ่านบทนี้แล้ว':'บันทึกว่าอ่านแล้ว'}</button></div></div><div class="lesson-grid"><article><section class="outcomes" id="outcomes"><h2>เมื่อจบบทนี้ คุณจะทำอะไรได้</h2><ul>${c.goals.map(g=>`<li>${esc(g)}</li>`).join('')}</ul>${c.id>1?`<p class="quiet" style="font-size:13px;margin:12px 0 0">พื้นฐานที่ใช้: <a href="#chapter/${c.id-1}">บท ${c.id-1}</a> และแนวคิดจากบทก่อนหน้า</p>`:''}</section>${c.sections.map((s,i)=>`<section class="lesson-section" id="section-${i}"><h2>${esc(s.title)}</h2>${s.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</section>`).join('')}${c.lab?`<section class="lab" id="lab"><div class="lab-header"><h2>ห้องทดลองแนวคิด</h2><span class="badge">${c.lab==='sql'?'SQLite จริง · Offline':'แบบจำลอง · ไม่เรียก Server จริง'}</span></div><div id="lab-content"></div></section>`:''}<section class="lesson-section" id="example"><h2>อ่านตัวอย่างและเหตุผล</h2>${codeBlock(c.example,'code-'+c.id)}${c.extraCode?codeBlock(c.extraCode,'code-extra-'+c.id):''}</section><section class="other-work" id="applications"><h2>นำไปใช้กับงานอื่นอย่างไร</h2><ul>${c.cases.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section><aside class="callout warning"><strong>จุดที่มักเข้าใจผิด</strong><p>${esc(c.pitfall)}</p></aside><section id="exercises"><p class="eyebrow">Practice / Chapter ${c.id}</p><h2>แบบฝึกท้ายบท</h2><p class="quiet">ลองตอบก่อนเปิดคำใบ้ ระบบให้แก้ได้ไม่จำกัดครั้งและอธิบายเหตุผลหลังตรวจ</p>${c.exercises.map((e,i)=>exerciseHTML(c,e,i)).join('')}<div class="exercise-summary" id="exercise-status" role="status"></div></section><section class="notes" id="notes"><h2>บันทึกด้วยภาษาของคุณ</h2><label for="chapter-notes">สรุปสิ่งที่เข้าใจแล้ว สิ่งที่ยังสับสน หรือยกสถานการณ์จากโปรเจกต์ของคุณ ช่องนี้บันทึกส่วนตัวและไม่ตรวจด้วย AI</label><textarea id="chapter-notes" rows="5" placeholder="ฉันจะใช้แนวคิดนี้กับ…">${esc(progress.notes[c.id]||'')}</textarea><p class="quiet" style="font-size:12px">บันทึกในเบราว์เซอร์เครื่องนี้ · ส่งออกความคืบหน้าได้ · ห้ามใส่ password หรือ token จริง</p></section><section id="references"><h2 style="font-size:18px">อ่านต่อจากเอกสารต้นทาง</h2><ul class="source-links">${c.refs.map(r=>`<li><a href="${sources[r][1]}" target="_blank" rel="noopener">${esc(sources[r][0])} ↗</a></li>`).join('')}</ul></section><div class="nextprev">${c.id>1?`<a href="#chapter/${c.id-1}"><small>← บทก่อนหน้า</small>${esc(chapters[c.id-2].title)}</a>`:`<a href="#home"><small>← กลับสารบัญ</small>ภาพรวมหลักสูตร</a>`}${c.id<21?`<a href="#chapter/${c.id+1}"><small>บทถัดไป →</small>${esc(chapters[c.id].title)}</a>`:`<a href="#home"><small>กลับมาทบทวน →</small>ดูความคืบหน้าทั้งหลักสูตร</a>`}</div>${footer()}</article><aside class="toc" aria-label="หัวข้อในบท"><span class="eyebrow">ในบทนี้</span><a href="#chapter/${c.id}/outcomes">เป้าหมาย</a>${c.sections.map((s,i)=>`<a href="#chapter/${c.id}/section-${i}">${esc(s.title)}</a>`).join('')}${c.lab?`<a href="#chapter/${c.id}/lab">ห้องทดลอง</a>`:''}<a href="#chapter/${c.id}/example">ตัวอย่างโค้ด</a><a href="#chapter/${c.id}/applications">งานอื่น</a><a href="#chapter/${c.id}/exercises">แบบฝึกท้ายบท</a><a href="#chapter/${c.id}/notes">บันทึกส่วนตัว</a></aside></div>`;}
function guide(){return `<p class="eyebrow">Learning guide</p><h1>เรียนอย่างไรให้ใช้เป็น</h1><p>เริ่มจากบท 1 ถ้ายังไม่เคยทำ Backend เรียนตามลำดับเพื่อให้ Schema,Auth,สิทธิ์และกฎเกมต่อกัน คาดการณ์ผลก่อนกดทดลอง แล้วอธิบายว่าทำไมผลจึงเป็นแบบนั้น</p><ol><li>อ่านสถานการณ์และเป้าหมายบท คำศัพท์ใหม่มีคำอธิบายก่อนใช้</li><li>อ่านเนื้อหาและลองห้องทดลอง เฉพาะแนวคิดที่การเห็นเหตุการณ์ช่วยให้เข้าใจ</li><li>ตรวจโค้ดพร้อมคำอธิบาย ตัวอย่างที่เป็น fragment หรือ pseudocode จะระบุชัด ไม่ใช่สคริปต์ที่คัดลอกแล้วรันได้ทั้งระบบ</li><li>ทำแบบฝึกท้ายบทสามข้อ เปิดคำใบ้ทีละขั้นและแก้จนเข้าใจเหตุผล เฉลยเปิดได้แต่ไม่เพิ่มคะแนนเอง</li><li>จดสรุปด้วยคำของคุณ แล้วลองนำแนวคิดไปอธิบายโปรเจกต์อื่น</li></ol><div class="callout"><strong>การฝึก SQL</strong><p>ช่อง SQL ใช้ SQLite ผ่าน sql.js และรันจริงใน Web Worker ไม่มีข้อมูลออกไป Server รองรับ SQL พื้นฐาน,JOIN,Constraints และ transaction แบบ SQLite แต่ไม่ใช่ PostgreSQL จึงไม่มี auth.uid(),jsonb หรือ SELECT FOR UPDATE แบบ PostgreSQL</p><p>การตรวจคำตอบ SQL เปรียบเทียบผลกับ query อ้างอิงหลายชุดข้อมูล ถ้าเป็นโจทย์แก้ข้อมูลจะตรวจสภาพตารางหลังคำสั่งด้วย ไม่ประเมิน performance หรือความเหมาะสมใน production</p></div><h2>ความคืบหน้า</h2><p>คำตอบ คำใบ้ คะแนนและบันทึกเก็บใน localStorage ของเบราว์เซอร์นี้ แยกจากบัญชี Supabase การล้างข้อมูลเว็บหรือเปลี่ยน origin/เครื่องอาจทำให้ไม่เห็นข้อมูลเดิม ใช้ส่งออก/นำเข้าไฟล์ JSON เพื่อย้ายเครื่องหรือสำรองก่อนปิด</p><p>ไม่มีข้อจำกัดเวลาหรือบทที่ล็อก การอ่านแล้วกับการผ่านแบบฝึกเป็นคนละสถานะ การผ่านแบบฝึกช่วยเช็กแนวคิด ไม่ใช่ใบรับรองว่าระบบ production ปลอดข้อผิดพลาด</p><button data-action="export" class="primary">ส่งออกความคืบหน้า</button> <button data-action="import">นำเข้าไฟล์</button><div class="callout warning"><strong>สภาพแวดล้อมจริง</strong><p>เว็บนี้ไม่ต้องกรอก key,password หรือ token จริง เมื่อไปใช้ Supabase ให้แยกโปรเจกต์พัฒนา อ่านเอกสารต้นทางของ SDK รุ่นที่ติดตั้ง และตรวจสิทธิ์ด้วย session ของผู้เล่นจริง</p></div><a class="button" href="#chapter/1">เริ่มบท 1 →</a>${footer()}`;}
const glossaryData=[['Client','โค้ดฝั่งผู้ใช้ เช่น Unity ที่ผู้เล่นควบคุมเครื่องได้'],['Backend','บริการเบื้องหลัง: ตัวตน API กฎ และการจัดเก็บ'],['API / Contract','ช่องทางและสัญญาข้อมูลที่ระบบตกลงใช้คุยกัน'],['HTTP / JSON','โปรโตคอลคำขอ–คำตอบ / รูปแบบข้อมูล'],['Schema','โครงสร้างข้อมูล ชนิด คีย์และข้อกำหนด'],['Primary / Foreign Key','รหัสประจำแถว / การอ้างรหัสในตารางอื่น'],['Authentication','ตรวจว่าผู้เรียกคือใคร'],['Authorization','ตรวจว่าผู้เรียกมีสิทธิ์ทำอะไร'],['Access / Refresh Token','หลักฐานอายุสั้นสำหรับคำขอ / ตัวใช้ขอคู่ token ใหม่'],['Session','สถานะการเข้าใช้พร้อม token ของผู้เล่น'],['RLS / Grant','นโยบายระดับแถว / สิทธิ์ประเภทการทำงาน'],['RPC','เรียก function ระยะไกลผ่าน API'],['Transaction','ชุดการเปลี่ยนที่ยืนยันหรือย้อนด้วยกัน'],['Race Condition','ผลขึ้นกับการสลับลำดับของงานที่เกิดพร้อมกัน'],['Idempotency','ส่ง action เดิมซ้ำแล้วไม่เกิดผลเพิ่ม'],['Revision','เวอร์ชันข้อมูลสำหรับตรวจ snapshot เก่าก่อนเขียน'],['Migration','ประวัติเปลี่ยนโครงสร้างฐานข้อมูลตามลำดับ'],['Snapshot / Delta','สภาพข้อมูลครบตามขอบเขต / เฉพาะส่วนที่เปลี่ยน'],['Fallback','ทางเลือกที่กำหนดไว้เมื่อค่าหรือบริการใหม่ใช้ไม่ได้'],['Observability','ข้อมูลและวิธีสังเกตว่าเกิดอะไรขึ้นกับระบบ']];
function sourcesPage(){return `<p class="eyebrow">References & design notes</p><h1>ที่มาของรูปแบบและเอกสาร</h1><p>บทเรียนภาษาไทย ตัวอย่าง แบบฝึก และตัวจำลองเขียนขึ้นสำหรับคอร์สนี้ รูปแบบการสอนและการนำทางปรับจากแนวทางที่เผยแพร่ต่อสาธารณะ ไม่ได้คัดลอกเนื้อหาคอร์สหรืออ้างว่าตรวจรับรองโดยเจ้าของแหล่งอ้างอิง</p><ul><li><a href="https://squidfunk.github.io/mkdocs-material/" target="_blank" rel="noopener">Material for MkDocs</a> — แนวทางแยกหน้าเนื้อหา สารบัญย่อย code block และการค้นหา; หน้านี้ใช้ CSS/JavaScript ที่เขียนใหม่ ไม่ได้ติดตั้งธีมหรือ build system ของ MkDocs</li><li><a href="https://carpentries.github.io/lesson-development-training/lesson-design.html" target="_blank" rel="noopener">The Carpentries · Lesson Design</a> — เริ่มจากผลการเรียนรู้และออกแบบแบบฝึกที่ตรวจความเข้าใจ</li><li><a href="https://developer.mozilla.org/en-US/docs/Learn_web_development" target="_blank" rel="noopener">MDN Learn</a> — แนวทางแยกแบบฝึกแนวคิดกับโจทย์ประยุกต์ ใช้คำใบ้ เฉลย และ reset เพื่อเรียนซ้ำ</li></ul><h2>เอกสารเทคนิค</h2><p>เอกสารอ่านเมื่อ 10 ตุลาคม 2026 ส่วนราคา API และแพ็กเกจอาจเปลี่ยน โปรดดูต้นทางก่อนใช้จริง ตัวอย่างราคาหรือเวลาทั้งหมดใน lab เป็นสมมติฐานที่ระบุ ไม่ใช่ข้อมูลจากระบบของคุณ</p><ul class="source-links">${Object.values(sources).map(([t,u])=>`<li><a href="${u}" target="_blank" rel="noopener">${esc(t)}</a></li>`).join('')}</ul><h2>SQL Engine</h2><p>ฝัง <a href="https://github.com/sql-js/sql.js" target="_blank" rel="noopener">sql.js 1.13.0</a> (SQLite ผ่าน WebAssembly) ใน HTML เพื่อทำงาน offline SQLite เป็น public domain และ sql.js เป็น MIT; เก็บประกาศสิทธิ์ไว้ด้านล่าง</p><details><summary>sql.js License</summary><pre>${esc(SQLJS_LICENSE)}</pre></details>${footer()}`;}
function route(){
 const h=location.hash.slice(1)||'home',m=h.match(/^chapter\/(\d+)(?:\/([\w-]+))?$/),next=m?Number(m[1]):0;
 if(m&&next>=1&&next<=21){
  if(active!==next||!$('#outcomes')){active=next;labState={};progress.last=next;save();$('#view').innerHTML=lesson(chapters[next-1]);if(chapters[next-1].lab)renderLab();document.title=`บท ${next} · ${chapters[next-1].title} — Backend Fieldnotes`;window.scrollTo(0,0);}
  if(m[2])setTimeout(()=>$('#'+m[2])?.scrollIntoView(),0);
 }else{
  active=0;
  if(h==='guide')$('#view').innerHTML=guide();
  else if(h==='sources')$('#view').innerHTML=sourcesPage();
  else if(h==='glossary')$('#view').innerHTML=`<p class="eyebrow">Glossary</p><h1>ศัพท์ที่ใช้ตลอดหลักสูตร</h1><dl class="glossary">${glossaryData.map(([t,d])=>`<div><dt>${esc(t)}</dt><dd>${esc(d)}</dd></div>`).join('')}</dl>${footer()}`;
  else if(h.startsWith('search/'))renderSearch(decodeURIComponent(h.slice(7)));
  else $('#view').innerHTML=home();
  document.title='Backend Fieldnotes — ห้องเรียน Backend สำหรับ Unity';window.scrollTo(0,0);
 }
 updateNav();closeMenu();
}
function renderSearch(term){const t=term.toLocaleLowerCase();const results=chapters.filter(c=>[c.title,c.lead,...c.goals,...c.sections.flatMap(s=>[s.title,...s.paragraphs]),c.example.code,...c.exercises.map(e=>e.prompt)].join(' ').toLocaleLowerCase().includes(t));$('#view').innerHTML=`<p class="eyebrow">Search the course</p><h1>ค้นหา “${esc(term)}”</h1><p class="quiet">พบ ${results.length} บท · ค้นทั้งหัวข้อ เนื้อหา โค้ด และโจทย์</p><div class="search-results">${results.map(c=>`<a class="search-result" href="#chapter/${c.id}"><strong>บท ${c.id} · ${esc(c.title)}</strong><p>${esc(c.lead)}</p></a>`).join('')||'<p>ไม่พบคำนี้ ลองใช้ศัพท์อังกฤษหรือคำสั้น เช่น Auth, เวลา, lock หรือ SQL</p>'}</div>${footer()}`;}
function closeMenu(){$('#sidebar').classList.remove('open');$('#backdrop').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');}
$('#menu').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#backdrop').classList.toggle('open',open);$('#menu').setAttribute('aria-expanded',String(open));if(open)$('#chapter-nav a').focus();};
$('#backdrop').onclick=closeMenu;document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();$('#menu').focus();}});
$('#theme').onclick=()=>{progress.theme=progress.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=progress.theme;save();};
$('#search').addEventListener('input',e=>{clearTimeout(searchTimer);const text=e.target.value.trim();searchTimer=setTimeout(()=>{if(text)location.hash='search/'+encodeURIComponent(text);else if(location.hash.startsWith('#search/'))location.hash='home';},250);});
function changedAnswer(id,value){const a=progress.answers[id]||{attempts:0};a.value=value;a.correct=false;a.feedback='';progress.answers[id]=a;save();const feedbackEl=$('#feedback-'+id);if(feedbackEl)feedbackEl.innerHTML='';updateNav();}
document.addEventListener('input',e=>{const t=e.target as HTMLInputElement;if(t.dataset.answer)changedAnswer(t.dataset.answer,t.type==='radio'?Number(t.value):t.value);if(t.id==='chapter-notes'){progress.notes[active]=t.value;save();}if(t.dataset.labInput)labInput(t);});
document.addEventListener('change',e=>{const t=e.target as HTMLInputElement;if(t.dataset.labChange)labInput(t);});
document.addEventListener('click',async e=>{
 const b=(e.target as Element).closest('button') as HTMLButtonElement|null;if(!b)return;
 if(b.dataset.grade)await grade(b.dataset.grade,b);
 if(b.dataset.hint){const id=b.dataset.hint;progress.answers[id]||={attempts:0};progress.answers[id].hint=true;$('#hint-'+id).hidden=false;save();}
 if(b.dataset.reset){delete progress.answers[b.dataset.reset];save();refreshExercise(b.dataset.reset);updateNav();}
 if(b.dataset.move){const id=b.dataset.move,[c,i]=findExercise(id),a=progress.answers[id]||{},arr=Array.isArray(a.value)?a.value.slice():defaultOrder(c.exercises[i]),pos=Number(b.dataset.pos),next=pos+Number(b.dataset.direction);[arr[pos],arr[next]]=[arr[next],arr[pos]];changedAnswer(id,arr);refreshExercise(id);}
 if(b.dataset.read){const id=Number(b.dataset.read);if(!progress.read.includes(id))progress.read.push(id);save();b.textContent='✓ อ่านบทนี้แล้ว';toast('บันทึกว่าอ่านแล้ว · ผ่านบทเมื่อทำแบบฝึกครบ');}
 if(b.dataset.copy){const text=$('#'+b.dataset.copy).textContent;try{await navigator.clipboard.writeText(text);toast('คัดลอกโค้ดแล้ว');}catch{toast('คัดลอกอัตโนมัติไม่ได้ เลือกข้อความในโค้ดแล้วคัดลอกได้');}}
 if(b.dataset.action==='export'){const blob=new Blob([JSON.stringify(progress,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='backend-fieldnotes-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('ส่งออกคำตอบและบันทึกเป็น JSON');}
 if(b.dataset.action==='import')$('#import-file').click();
 if(b.dataset.labAction)await labAction(b.dataset.labAction,b);
});
$('#import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2e6)throw Error('ไฟล์ใหญ่เกิน 2 MB');const imported=validProgress(JSON.parse(await f.text()));progress=imported;save();document.documentElement.dataset.theme=progress.theme;active=0;route();toast('นำเข้าความคืบหน้าแล้ว');}catch(err){toast('นำเข้าไม่ได้: '+err.message);}e.target.value='';};
function findExercise(id){const [n,i]=id.split('-').map(Number);return [chapters[n-1],i];}
function refreshExercise(id){const [c,i]=findExercise(id);$('#exercise-'+id).outerHTML=exerciseHTML(c,c.exercises[i],i);}
async function grade(id,b){
 const [c,i]=findExercise(id),q=c.exercises[i],a=progress.answers[id]||{attempts:0};let ok=false,detail='';
 if(q.type==='mc'){if(a.value===undefined){toast('เลือกคำตอบก่อนตรวจ');return;}ok=a.value===q.answer;}
 if(q.type==='text'){const value=String(a.value??'').trim().replace(/,/g,'');if(!value){toast('ใส่คำตอบก่อนตรวจ');return;}ok=q.answers.some(x=>value===x);}
 if(q.type==='order'){const arr=a.value??defaultOrder(q);ok=arr.every((v,j)=>v===j);a.value=arr;}
 if(q.type==='sql'){
  const text=String(a.value??q.starter);a.value=text;b.disabled=true;b.textContent='กำลังรันและตรวจ…';
  try{const result=await sqlRun({code:text,solution:q.solution,mode:'grade',kind:q.check.kind});ok=result.correct;detail=result.detail;}catch(err){detail='SQL ทำงานไม่สำเร็จ: '+err.message;}finally{b.disabled=false;b.textContent='ตรวจคำตอบ';}
 }
 a.attempts=(a.attempts||0)+1;a.correct=ok;a.feedback=ok?'✓ ถูกต้อง — '+q.why:'ยังไม่ตรงเงื่อนไข — '+(detail||'ลองทบทวนคำถามหรือเปิดคำใบ้ แล้วตรวจใหม่ได้');progress.answers[id]=a;save();$('#feedback-'+id).innerHTML=`<div class="feedback ${ok?'success':'error'}">${esc(a.feedback)}</div>`;updateNav();
}
const seedSql=`PRAGMA foreign_keys=ON; CREATE TABLE players(id TEXT PRIMARY KEY,name TEXT NOT NULL); INSERT INTO players VALUES('A','Mali'),('B','Niran'); CREATE TABLE items(id TEXT PRIMARY KEY,name TEXT NOT NULL); INSERT INTO items VALUES('wood','Wood'),('stone','Stone'),('seed','Seed'),('chair','Chair'); CREATE TABLE inventory(user_id TEXT NOT NULL REFERENCES players(id),item_id TEXT NOT NULL REFERENCES items(id),quantity INTEGER NOT NULL CHECK(quantity>=0),PRIMARY KEY(user_id,item_id)); INSERT INTO inventory VALUES('A','wood',10),('A','stone',4),('B','wood',3),('B','seed',5);`;
async function sqlRun(task){
 const workerCode=$('#sqlengine').textContent+`\nconst seed=${JSON.stringify(seedSql)}; const base64=${JSON.stringify(WASM_BASE64)}; const bytes=Uint8Array.from(atob(base64),c=>c.charCodeAt(0)); const ready=initSqlJs({wasmBinary:bytes});\nself.onmessage=async function(event){try{const SQL=await ready;const t=event.data;function dbFor(fixture){const d=new SQL.Database();d.run(seed);if(fixture===1)d.run("UPDATE inventory SET quantity=quantity+7; INSERT INTO inventory VALUES('A','seed',2);");return d;}function result(d,code){return d.exec(code).map(x=>({columns:x.columns,values:x.values.slice(0,500)}));}function dump(d){return ['players','items','inventory'].map(n=>d.exec('SELECT * FROM '+n+' ORDER BY 1,2'));}if(t.mode==='grade'){let correct=true;for(let fixture=0;fixture<2;fixture++){const a=dbFor(fixture),b=dbFor(fixture);try{const actual=result(a,t.code),expected=result(b,t.solution);if(t.kind==='result'){const x=actual.at(-1)?.values,y=expected.at(-1)?.values;if(JSON.stringify(x)!==JSON.stringify(y)||JSON.stringify(dump(a))!==JSON.stringify(dump(b)))correct=false;}else{if(JSON.stringify(dump(a))!==JSON.stringify(dump(b)))correct=false;}}finally{a.close();b.close();}}self.postMessage({correct,detail:correct?'':'ผลลัพธ์หรือข้อมูลหลังคำสั่งไม่ตรงในหนึ่งชุดขึ้นไป ตรวจคอลัมน์,WHERE,ลำดับแถว และอย่าเขียนคำตอบเป็นค่าคงที่'});}else{const d=dbFor(0);try{const before=d.exec('SELECT total_changes()')[0].values[0][0];const out=result(d,t.code);const changes=d.exec('SELECT total_changes()')[0].values[0][0]-before;self.postMessage({out,changes});}finally{d.close();}}}catch(e){self.postMessage({error:e.message});}};`;
 const url=URL.createObjectURL(new Blob([workerCode],{type:'text/javascript'}));const worker=new Worker(url);URL.revokeObjectURL(url);
 return new Promise<any>((resolve,reject)=>{const timer=setTimeout(()=>{worker.terminate();reject(Error('เกินเวลา 6 วินาที หยุดคำสั่งแล้ว ลอง query ที่จำกัดข้อมูล'));},6000);worker.onmessage=e=>{clearTimeout(timer);worker.terminate();if(e.data.error)reject(Error(e.data.error));else resolve(e.data);};worker.onerror=e=>{clearTimeout(timer);worker.terminate();reject(Error(e.message||'เปิด SQLite engine ไม่สำเร็จ'));};worker.postMessage(task);});
}
function resultTable(out){return out.map((r,i)=>`<div class="table-wrap"><table><caption>ผลลัพธ์ชุด ${i+1} · แสดงสูงสุด 500 แถว</caption><thead><tr>${r.columns.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${r.values.map(row=>`<tr>${row.map(v=>`<td>${v===null?'<i>NULL</i>':esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`).join('')||'<p>คำสั่งเสร็จแล้ว ไม่มี result set ให้แสดง</p>';}
