function button(action,text,primary=false){return `<button class="${primary?'primary':''}" data-lab-action="${action}">${text}</button>`;}
function input(name,label,value,type='number'){return `<label>${label}<input type="${type}" value="${esc(value)}" data-lab-input="${name}" ${type==='number'?'min="0" max="1000000000"':''}></label>`;}
function select(name,label,choices,value){return `<label>${label}<select data-lab-change="${name}">${choices.map(([v,t])=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${t}</option>`).join('')}</select></label>`;}
function toggle(name,label,value){return `<label class="checkline"><input type="checkbox" data-lab-change="${name}" ${value?'checked':''}>${label}</label>`;}
function stats(items){return `<div class="data-pair">${items.map(([label,v])=>`<div>${label}<strong>${esc(v)}</strong></div>`).join('')}</div>`;}
function logView(){return labState.logs?.length?`<div class="log" aria-label="ลำดับเหตุการณ์">${labState.logs.map(t=>`<p>${esc(t)}</p>`).join('')}</div>`:'';}
function output(text){return `<div class="lab-output" aria-live="polite">${text}</div>`;}
