 const defs={authority:{client:10,server:10,trust:'server'},http:{method:'POST',token:'valid',body:'{"recipe_id":"chair"}'},schema:{owner:'A',item:'wood',quantity:2,unique:true,fk:true,rows:[['A','wood',10]]},race:{mode:'locked',step:0,wood:10,chairs:0},auth:{kind:'none',verified:false,pending:false,uid:null},session:{time:0,expiry:5,refresh:true,uid:'A',rotation:1,persist:true},rls:{user:'A',grant:true,policy:'owner',rls:true,write:false,secret:false,op:'read'},response:{result:'success'},time:{server:100,phone:0,ready:400,harvested:false},craft:{wood:10,chairs:0,fail:false},retry:{wood:20,chairs:0,id:'action-x',receipt:true,drop:true,done:{}},shelter:{wood:20,level:1,status:'idle',server:100,ready:null},layout:{selected:'chair-1',positions:{'chair-1':0,'table-1':5},saved:{'chair-1':0,'table-1':5},revision:4,expected:4,bad:false},config:{text:JSON.stringify({schema_version:1,version:12,crop_seconds:300},null,2),last:{schema_version:1,version:11,crop_seconds:600},network:true},quest:{server:18,day:10,zone:'bangkok',clientDay:10,progress:{},claims:{},seeds:0},budget:{dau:100,sessions:2,requests:15,kb:2,quota:5},capstone:{authority:'server',owner:'rls',writes:'rpc',concurrency:'lock',retry:'same',claim:'unique',revision:'check',config:'fallback'}};
 labState={...(defs[id]||{}),logs:[],message:'',initialized:true};
